"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[75361],{13092:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"qiangguo/contradiction","title":"","description":"Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/contradiction.md","sourceDirName":"qiangguo","slug":"/qiangguo/contradiction","permalink":"/en/qiangguo/contradiction","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"contradiction","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u6570\u5b66\u7f51\u53cb\u4e0d\u8981\u800d\u8d56\uff0c\u4f60\u4e0d\u4f1a\u5065\u5fd8\u5230\u8fde\u81ea\u5df1\u8bf4\u8fc7\u7684\u8bdd\u90fd\u4e0d\u8bb0\u5f97\u4e86\uff1f","permalink":"/en/qiangguo/dontbeniggling"},"next":{"title":"\u53ef\u601c\u7684\u5de6\u6d3e\u7adf\u7136\u8981\u5356\u8eab\u7ed9\u53ef\u7b11\u7684\u201c\u963f\u7f57\u4e0d\u53ef\u80fd\u5b9a\u7406\u201d\uff1f","permalink":"/en/qiangguo/arrowtheorem"}}');var o=n(74848),a=n(28453);const r={id:"contradiction",title:"",hide_table_of_contents:!0},s='To the Netizen "Mathematics" Who Doesn\'t Even Understand Proof by Contradiction -- Please Change Your Name!',h={},c=[];function m(e){const t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"to-the-netizen-mathematics-who-doesnt-even-understand-proof-by-contradiction----please-change-your-name",children:'To the Netizen "Mathematics" Who Doesn\'t Even Understand Proof by Contradiction -- Please Change Your Name!'})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n"}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:'In mathematics, proof by contradiction is one of the most basic methods. Without proof by contradiction, there would essentially be no mathematics, and without mathematics, there would be no computers either. Yet this netizen calling themselves "Mathematics" doesn\'t even understand proof by contradiction -- please change your name!'}),"\n",(0,o.jsx)(t.p,{children:'After this ID posted "Netizen Mathematics, If You Have Any Academic Integrity, Stand Up and Admit Your Error!", this "Mathematics" person produced a post titled "Miss Chan\'s Academic Criticism of Me Is Quite Baffling," containing this statement: "To refute my view, one must specifically identify a law of motion that cannot be stored in a computer." Following the same logic, to prove that prime numbers are infinite, one must find a method, an actual program, to demonstrate that primes are infinite.'}),"\n",(0,o.jsx)(t.p,{children:"However, in mathematics, there is no need to find an actual program to prove that primes are infinite, because mathematics has a standard method called proof by contradiction: if primes were finite, multiplying all primes together and adding one would certainly not be divisible by any prime, which contradicts the divisibility properties of natural numbers -- therefore primes are infinite. Here, one can prove primes are infinite without even knowing a single prime number. Furthermore, even without knowing any transcendental number, we can use proof by contradiction to show that transcendental numbers are far more numerous than all algebraic numbers combined. This is the power of mathematical methods!"}),"\n",(0,o.jsx)(t.p,{children:'Since this "Mathematics" netizen doesn\'t even understand the most basic mathematical methods, I ask this "Mathematics" netizen to please change their name. The proof from this ID is appended below:'}),"\n",(0,o.jsx)(t.p,{children:'As for that "Mathematics" ID who regularly makes logical blunders, he recently proclaimed as if discovering a new continent: "From a mathematical theory standpoint, dichotomy, that is, using binary numbers, can express the entirety of human thought and laws of motion, because these thoughts can all be stored in binary computers." I have no idea what kind of "mathematical theory" this supposed Mathematics ID is referring to -- does merely claiming a Mathematics ID entitle one to spout mathematical nonsense? Very well, let us examine this so-called discovery or proclamation from this Mathematics ID in a thoroughly mathematical manner:'}),"\n",(0,o.jsx)(t.p,{children:'Let us assume this proclamation holds -- that all human thoughts and laws of motion can be represented using binary numbers. Then we line up these binary numbers representing all human thoughts and laws of motion. Now consider a binary number whose Nth digit differs from the Nth digit of the Nth binary number in our lineup (for example, if the latter is 1, the former is 0, and vice versa). Clearly, this binary number is not among the binary numbers representing all human thoughts and laws of motion, yet this binary number represents the following thought: "its Nth digit differs from the Nth digit of the Nth binary number in the lineup." In other words, this thought is not contained within the totality of human thoughts and laws of motion -- and this is a contradiction. By the simplest proof by contradiction, the assumption that "all human thoughts and laws of motion can be represented using binary numbers" does not hold. Not all human thoughts and laws of motion can be represented using binary numbers.'}),"\n",(0,o.jsx)(t.p,{children:'The proof strategy above is actually not an invention of this ID. It is a classical mathematical proof method with a popular name: the "diagonal method," which first appeared in Cantor\'s series of proofs on set theory in the 19th century. Leaving aside the mathematical developments of the 20th century, which exceeded all previous centuries combined, anyone with even a basic understanding of this 19th-century mathematical knowledge could not possibly proclaim such an absurd proposition.'})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>s});var i=n(96540);const o={},a=i.createContext(o);function r(e){const t=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);